-- Values of cstring, unknown and "any", and PL/pgSQL record arguments.
SELECT 'abc'::cstring;
SELECT pg_typeof('abc'::cstring);
SELECT 'abc'::cstring::text;
SELECT 'x'::varchar::cstring, 'x'::name::cstring, 'x'::bpchar::cstring;
SELECT 'x'::cstring::varchar, 'x'::cstring::name, 'x'::cstring::bpchar;
SELECT 'abc'::unknown;
SELECT pg_typeof('abc'::unknown);
SELECT '1'::"any";
SELECT pg_typeof('a'::"any");
SELECT 5::"any";
SELECT 5::cstring;
SELECT 5::unknown;
SELECT 'x'::cstring::int;
SELECT 'x'::unknown::int;
SELECT 'x'::unknown::text, 'x'::unknown::cstring, 'x'::"any"::text;
SELECT now()::cstring;
SELECT true::cstring;
SELECT NULL::cstring, NULL::"any", NULL::unknown;
SELECT 'a'::cstring IS NULL;
SELECT 'a'::cstring || 'b';
SELECT 'x'::cstring::unknown;
CREATE FUNCTION rf(r record) RETURNS text LANGUAGE plpgsql AS $$ BEGIN RETURN r::text; END $$;
SELECT rf(ROW(1, 'a'));
CREATE FUNCTION rf2(r record) RETURNS int LANGUAGE plpgsql AS $$ BEGIN RETURN r.f1; END $$;
SELECT rf2(ROW(7, 'a'));
CREATE TABLE t (a int, b text);
INSERT INTO t VALUES (3, 'z');
CREATE FUNCTION rf3(r record) RETURNS text LANGUAGE plpgsql AS $$ BEGIN RETURN r.b || r.a; END $$;
SELECT rf3(t) FROM t;
SELECT rf2(NULL);
CREATE FUNCTION rf4(r record, n int) RETURNS int LANGUAGE plpgsql AS $$ DECLARE x record; BEGIN x := r; RETURN x.a + n; END $$;
SELECT rf4(t, 10) FROM t;
SELECT rf(1);
SELECT pg_get_function_arguments('rf4'::regproc);
CREATE FUNCTION rs(r record) RETURNS int LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION rv() RETURNS text LANGUAGE plpgsql AS $$ DECLARE x record; BEGIN x := ROW(1, 'x'); RETURN x.b; END $$;
SELECT rv();
DROP TABLE t;
